package mx.gob.sedesol.basegestor.gestionescolar.v2;
import static org.testng.Assert.*; import java.util.Date; import org.testng.annotations.Test; import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.*; import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;
/** F5D-U: clasificación central oferta/cupo RN-6.1.4. */
public class EvaluacionCurricularV2Fase5DTest { private final EvaluacionCurricularV2ServiceImpl s=new EvaluacionCurricularV2ServiceImpl();
 @Test public void candidataQuintoSeEvaluaAunqueObjetivoSeaOtro(){ContextoEvaluacionCurricularV2DTO z=c(null);z.setSemestreObjetivo(3);assertFalse(x(z).getOfertasPendientesRn614().isEmpty());}
 @Test public void disponible(){assertE(null,EstadoOfertaPendienteRn614V2.DISPONIBLE,false,false);}
 @Test public void noOfertada(){assertE(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO,EstadoOfertaPendienteRn614V2.NO_OFERTADA_EN_PERIODO,true,false);}
 @Test public void fueraBloque(){assertE(CausaIndisponibilidadOfertaV2.FUERA_BLOQUE_VIGENTE,EstadoOfertaPendienteRn614V2.FUERA_DE_BLOQUE_VIGENTE,true,false);}
 @Test public void sinGrupoInstitucional(){assertE(CausaIndisponibilidadOfertaV2.SIN_GRUPO_ACTIVO_INSTITUCIONAL,EstadoOfertaPendienteRn614V2.SIN_GRUPO_ACTIVO_DECISION_INSTITUCIONAL,true,false);}
 @Test public void otraInstitucional(){assertE(CausaIndisponibilidadOfertaV2.OTRA_INDISPONIBILIDAD_INSTITUCIONAL,EstadoOfertaPendienteRn614V2.OTRA_CONDICION_INSTITUCIONAL_OBJETIVA,true,false);}
 @Test public void sinCupoNoEsOferta(){assertE(CausaIndisponibilidadOfertaV2.SIN_CUPO,EstadoOfertaPendienteRn614V2.SIN_CUPO_CAPACIDAD,false,true);}
 @Test public void faltaOfertaAlimentaRn613(){assertTrue(t(x(c(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO)),CodigoSupuestoAvanceCondicionadoV2.FALTA_OFERTA_SUFICIENTE));}
 @Test public void cupoNoAlimentaRn613(){assertFalse(t(x(c(CausaIndisponibilidadOfertaV2.SIN_CUPO)),CodigoSupuestoAvanceCondicionadoV2.FALTA_OFERTA_SUFICIENTE));}
 @Test public void incertidumbre(){ContextoEvaluacionCurricularV2DTO z=c(null);z.getUnidades().get(0).setOfertada(null);z.getUnidades().get(0).setGrupoActivoConocido(null);assertEquals(x(z).getOfertasPendientesRn614().get(0).getEstado(),EstadoOfertaPendienteRn614V2.REQUIERE_REVISION);}
 @Test public void conservaEstado(){ContextoEvaluacionCurricularV2DTO z=c(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO);assertEquals(x(z).getOfertasPendientesRn614().get(0).getEstadoCurricular(),EstadoUnidadCurricularV2.REPROBADA);}
 @Test public void deterministaSinEfecto(){ContextoEvaluacionCurricularV2DTO z=c(CausaIndisponibilidadOfertaV2.SIN_CUPO);assertEquals(x(z).getOfertasPendientesRn614().get(0).getEstado(),x(z).getOfertasPendientesRn614().get(0).getEstado());assertFalse(s.evaluarSombra(z).getEfectosProductivosAplicados());}
 private void assertE(CausaIndisponibilidadOfertaV2 a,EstadoOfertaPendienteRn614V2 e,boolean f,boolean cupo){EvaluacionOfertaPendienteRn614V2DTO q=x(c(a)).getOfertasPendientesRn614().get(0);assertEquals(q.getEstado(),e);assertEquals(q.getFaltaOferta(),Boolean.valueOf(f));assertEquals(q.getSinCupo(),Boolean.valueOf(cupo));}
 private EvaluacionCargaAcademicaV2DTO x(ContextoEvaluacionCurricularV2DTO z){return s.evaluarSombra(z).getEvaluacionCargaAcademica();} private boolean t(EvaluacionCargaAcademicaV2DTO q,CodigoSupuestoAvanceCondicionadoV2 c){for(SupuestoAvanceCondicionadoV2DTO v:q.getSupuestosAvanceTipificados())if(v.getCodigo()==c)return true;return false;}
 private ContextoEvaluacionCurricularV2DTO c(CausaIndisponibilidadOfertaV2 causa){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setIdPlan(1L);z.setPeriodoNormativo("2027-1");z.setSemestreObjetivo(5);z.setVersionReglas("PE2027-V1");z.setFechaEvaluacion(new Date(0));z.setActividadAcademicaComprobada(Boolean.TRUE);z.setPermanenciaDentroLimiteComprobada(Boolean.TRUE);z.setSeriacionComprobada(Boolean.TRUE);z.setEstructuraProgramaEducativoComprobada(Boolean.TRUE);z.setSancionImpedimentoConocida(Boolean.TRUE);z.setSancionImpedimentoRegistrada(Boolean.FALSE);UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(1L);u.setClave("P1");u.setTipoUd("Obligatoria");u.setSemestre(1);u.setEstado(EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(Boolean.TRUE);u.setReprobacionPeriodoPrevioConocida(Boolean.TRUE);u.setOfertada(Boolean.TRUE);u.setGrupoActivoConocido(Boolean.TRUE);u.setCupoDisponibleConocido(Boolean.TRUE);u.setCausaIndisponibilidadOferta(causa);z.getUnidades().add(u);UnidadEvaluacionCurricularV2DTO q=new UnidadEvaluacionCurricularV2DTO();q.setIdPrograma(5L);q.setClave("Q5");q.setTipoUd("Obligatoria");q.setSemestre(5);q.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);q.setOfertada(Boolean.TRUE);q.setGrupoActivoConocido(Boolean.TRUE);q.setCupoDisponibleConocido(Boolean.TRUE);z.getUnidades().add(q);return z;}}
